	FAILED_CASH_REGISTER_SALES_PY_SWDAY_NET_VAL,
	FAILED_CASH_REGISTER_RETURN_PY_SWDAY_NET_VAL,
	TOTAL
) COMMENT='Retail by store and day together with looked up revenues (previous year s same weekday value) to check, if PY_SWDAY columns are looked up correctly\ninput datasets:\ncore_dim.t_fact_retail_by_store_day_2\ncore_rel.t_cal_date_adjusted_relationship_2'
 as SELECT coalesce(fact.bus_dt,agg.cal_dt) AS bus_dt, coalesce(fact.int_org_sid, agg.int_org_sid) AS int_org_sid, fact.int_org_type_cd, fact.country_org_cd, fact.sales_cnt, fact.sales_bytd_cnt, fact.sales_py_cnt, fact.sales_py_bytd_cnt, fact.sales_py_swday_cnt, agg.prev_sw_day_sales_cnt, fact.sales_py_swday_bytd_cnt, fact.sales_qty, fact.sales_bytd_qty, fact.sales_py_qty, fact.sales_py_bytd_qty, fact.sales_py_swday_qty, agg.prev_sw_day_sales_qty, fact.sales_py_swday_bytd_qty, fact.return_cnt, fact.return_bytd_cnt, fact.return_py_cnt, fact.return_py_bytd_cnt, fact.return_py_swday_cnt, agg.prev_sw_day_return_cnt, fact.return_py_swday_bytd_cnt, fact.return_qty, fact.return_bytd_qty, fact.return_py_qty, fact.return_py_bytd_qty, fact.return_py_swday_qty, agg.prev_sw_day_return_qty, fact.return_py_swday_bytd_qty, fact.perf_adj_sales_cnt, fact.perf_adj_sales_bytd_cnt, fact.perf_adj_sales_py_cnt, fact.perf_adj_sales_py_bytd_cnt, fact.perf_adj_sales_py_swday_cnt, agg.prev_sw_day_perf_adj_sales_cnt, fact.perf_adj_sales_py_swday_bytd_cnt, fact.perf_adj_sales_qty, fact.perf_adj_sales_bytd_qty, fact.perf_adj_sales_py_qty, fact.perf_adj_sales_py_bytd_qty, fact.perf_adj_sales_py_swday_qty, agg.prev_sw_day_perf_adj_sales_qty, fact.perf_adj_sales_py_swday_bytd_qty, fact.perf_adj_return_cnt, fact.perf_adj_return_bytd_cnt, fact.perf_adj_return_py_cnt, fact.perf_adj_return_py_bytd_cnt, fact.perf_adj_return_py_swday_cnt, agg.prev_sw_day_perf_adj_return_cnt, fact.perf_adj_return_py_swday_bytd_cnt, fact.perf_adj_return_qty, fact.perf_adj_return_bytd_qty, fact.perf_adj_return_py_qty, fact.perf_adj_return_py_bytd_qty, fact.perf_adj_return_py_swday_qty, agg.prev_sw_day_perf_adj_return_qty, fact.perf_adj_return_py_swday_bytd_qty, fact.uom_cd, fact.turnover_net_val, fact.turnover_bytd_net_val, fact.turnover_py_net_val, fact.turnover_py_bytd_net_val, fact.turnover_py_swday_net_val, agg.prev_sw_day_turnover_net_val, fact.turnover_py_swday_bytd_net_val, fact.plan_turnover_net_val, fact.plan_turnover_bytd_net_val, fact.plan_turnover_py_net_val, fact.plan_turnover_py_bytd_net_val, fact.plan_turnover_py_swday_net_val, agg.prev_sw_day_plan_turnover_net_val, fact.plan_turnover_py_swday_bytd_net_val, fact.cash_register_sales_net_val, fact.cash_register_sales_bytd_net_val, fact.cash_register_sales_py_net_val, fact.cash_register_sales_py_bytd_net_val, fact.cash_register_sales_py_swday_net_val, agg.prev_sw_day_cash_register_sales_net_val, fact.cash_register_sales_py_swday_bytd_net_val, fact.cash_register_return_net_val, fact.cash_register_return_bytd_net_val, fact.cash_register_return_py_net_val, fact.cash_register_return_py_bytd_net_val, fact.cash_register_return_py_swday_net_val, agg.prev_sw_day_cash_register_return_net_val, fact.cash_register_return_py_swday_bytd_net_val, fact.eod_turnover_net_val, fact.booked_turnover_net_val, fact.turnover_gross_val, fact.turnover_bytd_gross_val, fact.turnover_py_gross_val, fact.turnover_py_bytd_gross_val, fact.turnover_py_swday_gross_val, agg.prev_sw_day_turnover_gross_val, fact.turnover_py_swday_bytd_gross_val, fact.cash_register_sales_gross_val, fact.cash_register_return_gross_val, fact.eod_turnover_gross_val, fact.curr_cd, fact.receipt_cnt, fact.receipt_bytd_cnt, fact.receipt_py_cnt, fact.receipt_py_bytd_cnt, fact.receipt_py_swday_cnt, agg.prev_sw_day_receipt_cnt, fact.receipt_py_swday_bytd_cnt, fact.cash_register_receipt_cnt, fact.eod_receipt_cnt, fact.booked_receipt_cnt, fact.plan_receipt_cnt, fact.plan_receipt_bytd_cnt, fact.plan_receipt_py_cnt, fact.plan_receipt_py_bytd_cnt, fact.plan_receipt_py_swday_cnt, agg.prev_sw_day_plan_receipt_cnt, fact.plan_receipt_py_swday_bytd_cnt, fact.dwh_created_tmsp, fact.dwh_updated_tmsp, fact.dwh_load_id, fact.dwh_node_cd, CASE WHEN ( COALESCE(fact.turnover_py_swday_net_val, -1) != COALESCE(prev_sw_day_turnover_net_val, -1) ) THEN 1 ELSE 0 END AS failed_turnover_py_swday_net_val, CASE WHEN ( COALESCE(fact.plan_turnover_py_swday_net_val, -1) != COALESCE(prev_sw_day_plan_turnover_net_val, -1) ) THEN 1 ELSE 0 END AS failed_plan_turnover_py_swday_net_val, CASE WHEN ( COALESCE(fact.turnover_py_swday_gross_val, -1) != COALESCE(prev_sw_day_turnover_gross_val, -1) ) THEN 1 ELSE 0 END AS failed_turnover_py_swday_gross_val, CASE WHEN ( COALESCE(fact.receipt_py_swday_cnt, -1) != COALESCE(prev_sw_day_receipt_cnt, -1) ) THEN 1 ELSE 0 END AS failed_receipt_py_swday_cnt, CASE WHEN ( COALESCE(fact.plan_receipt_py_swday_cnt, -1) != COALESCE(prev_sw_day_plan_receipt_cnt, -1) ) THEN 1 ELSE 0 END AS failed_plan_receipt_py_swday_cnt, CASE WHEN ( COALESCE(fact.sales_py_swday_cnt, -1) != COALESCE(prev_sw_day_sales_cnt, -1) ) THEN 1 ELSE 0 END AS failed_sales_py_swday_cnt, CASE WHEN ( COALESCE(fact.sales_py_swday_qty, -1) != COALESCE(prev_sw_day_sales_qty, -1) ) THEN 1 ELSE 0 END AS failed_sales_py_swday_qty, CASE WHEN ( COALESCE(fact.return_py_swday_cnt, -1) != COALESCE(prev_sw_day_return_cnt, -1) ) THEN 1 ELSE 0 END AS failed_return_py_swday_cnt, CASE WHEN ( COALESCE(fact.return_py_swday_qty, -1) != COALESCE(prev_sw_day_return_qty, -1) ) THEN 1 ELSE 0 END AS failed_return_py_swday_qty, CASE WHEN ( COALESCE(fact.perf_adj_sales_py_swday_cnt, -1) != COALESCE(prev_sw_day_perf_adj_sales_cnt, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_sales_py_swday_cnt, CASE WHEN ( COALESCE(fact.perf_adj_sales_py_swday_qty, -1) != COALESCE(prev_sw_day_perf_adj_sales_qty, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_sales_py_swday_qty, CASE WHEN ( COALESCE(fact.perf_adj_return_py_swday_cnt, -1) != COALESCE(prev_sw_day_perf_adj_return_cnt, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_return_py_swday_cnt, CASE WHEN ( COALESCE(fact.perf_adj_return_py_swday_qty, -1) != COALESCE(prev_sw_day_perf_adj_return_qty, -1) ) THEN 1 ELSE 0 END AS failed_perf_adj_return_py_swday_qty, CASE WHEN ( COALESCE(fact.cash_register_sales_py_swday_net_val, -1) != COALESCE(prev_sw_day_cash_register_sales_net_val, -1) ) THEN 1 ELSE 0 END AS failed_cash_register_sales_py_swday_net_val, CASE WHEN ( COALESCE(fact.cash_register_return_py_swday_net_val, -1) != COALESCE(prev_sw_day_cash_register_return_net_val, -1) ) THEN 1 ELSE 0 END AS failed_cash_register_return_py_swday_net_val, 1 AS TOTAL FROM ( SELECT * FROM core_dim.t_fact_retail_by_store_day_2 where bus_dt < current_date ) fact FULL OUTER JOIN ( SELECT prev_year_fact.int_org_sid AS int_org_sid, dr.cal_dt AS cal_dt, SUM (prev_year_fact.turnover_net_val) AS prev_sw_day_turnover_net_val, SUM (prev_year_fact.plan_turnover_net_val) AS prev_sw_day_plan_turnover_net_val, SUM (prev_year_fact.turnover_gross_val) AS prev_sw_day_turnover_gross_val, SUM (prev_year_fact.receipt_cnt) AS prev_sw_day_receipt_cnt, SUM (prev_year_fact.plan_receipt_cnt) AS prev_sw_day_plan_receipt_cnt, SUM (prev_year_fact.sales_cnt) as prev_sw_day_sales_cnt, SUM (prev_year_fact.sales_qty) as prev_sw_day_sales_qty, SUM (prev_year_fact.return_cnt) as prev_sw_day_return_cnt, SUM (prev_year_fact.return_qty) as prev_sw_day_return_qty, SUM (prev_year_fact.perf_adj_sales_cnt) as prev_sw_day_perf_adj_sales_cnt, SUM (prev_year_fact.perf_adj_sales_qty) as prev_sw_day_perf_adj_sales_qty, SUM (prev_year_fact.perf_adj_return_cnt) as prev_sw_day_perf_adj_return_cnt, SUM (prev_year_fact.perf_adj_return_qty) as prev_sw_day_perf_adj_return_qty, SUM (prev_year_fact.cash_register_sales_net_val) as prev_sw_day_cash_register_sales_net_val, SUM (prev_year_fact.cash_register_return_net_val) as prev_sw_day_cash_register_return_net_val FROM core_rel.t_cal_date_adjusted_relationship_2 dr INNER JOIN core_dim.t_fact_retail_by_store_day_2 prev_year_fact ON prev_year_fact.bus_dt = dr.rel_cal_dt AND dr.cal_dt_adjust_type_cd = 'W' AND dr.bus_year_diff = 1 WHERE dr.cal_dt < current_date GROUP BY prev_year_fact.int_org_sid, dr.cal_dt ORDER BY prev_year_fact.int_org_sid, dr.cal_dt ) AS agg ON fact.int_org_sid = agg.int_org_sid and fact.bus_dt = agg.cal_dt ORDER BY fact.int_org_sid, fact.bus_dt ASC;